## ----conceptual, echo=FALSE, fig.width=7, fig.height=4.2, fig.cap="Metafrontier decomposition for a single-input production function (diagram drawn with ggplot2; code in the supplementary materials). For Firm A, technical efficiency (TE) is the distance from observed output to the group frontier, the technology gap ratio (TGR) the distance from the group frontier to the metafrontier (solid black), and TE* = TE x TGR.", fig.alt="A line plot showing two group-specific production frontiers as upward-sloping dashed lines and a metafrontier as a solid black line above both. A point labelled Firm A sits below the Group 1 frontier. Two vertical segments from the firm to the group frontier (labelled TE) and from the group frontier to the metafrontier (labelled TGR) illustrate the efficiency decomposition."----
# Conceptual diagram of metafrontier decomposition
f_g1 <- function(x) 0.5 + 0.7 * x
f_g2 <- function(x) 1.3 + 0.45 * x
f_meta <- function(x) 1.4 + 0.58 * x

x_firm <- 2.5
y_firm <- 2.0
y_g1 <- f_g1(x_firm)
y_meta <- f_meta(x_firm)

ggplot(data.frame(x = c(0.5, 4.5)), aes(x = x)) +
  stat_function(fun = f_g1, aes(colour = "Group 1 frontier"),
                linetype = "dashed", linewidth = 0.8) +
  stat_function(fun = f_g2, aes(colour = "Group 2 frontier"),
                linetype = "dashed", linewidth = 0.8) +
  stat_function(fun = f_meta, aes(colour = "Metafrontier"),
                linetype = "solid", linewidth = 1) +
  geom_point(aes(x = x_firm, y = y_firm), size = 3, shape = 16) +
  geom_segment(aes(x = x_firm + 0.02, y = y_firm,
                   xend = x_firm + 0.02, yend = y_g1),
               colour = "#2166AC", linewidth = 0.7,
               arrow = arrow(length = unit(0.12, "cm"), ends = "both")) +
  geom_segment(aes(x = x_firm + 0.02, y = y_g1,
                   xend = x_firm + 0.02, yend = y_meta),
               colour = "#B2182B", linewidth = 0.7,
               arrow = arrow(length = unit(0.12, "cm"), ends = "both")) +
  annotate("text", x = x_firm + 0.18, y = (y_firm + y_g1) / 2,
           label = "TE", fontface = "italic", size = 4, hjust = 0) +
  annotate("text", x = x_firm + 0.18, y = (y_g1 + y_meta) / 2,
           label = "TGR", fontface = "italic", size = 4, hjust = 0) +
  annotate("text", x = x_firm - 0.15, y = y_firm - 0.08,
           label = "Firm A", size = 3.5, hjust = 1) +
  scale_colour_manual(
    values = c("Group 1 frontier" = "#2166AC",
               "Group 2 frontier" = "#D6604D",
               "Metafrontier" = "black"),
    guide = guide_legend(override.aes = list(
      linetype = c("dashed", "dashed", "solid")))
  ) +
  labs(x = "Input (log)", y = "Output (log)", colour = NULL) +
  theme_minimal(base_size = 12) +
  theme(legend.position = "bottom",
        panel.grid.minor = element_blank())


