## ----monte-carlo, cache=TRUE, echo=FALSE------------------------------
set.seed(123)
n_reps <- 500
beta_true <- c(1.0, 0.5, 0.3)
mc_results <- vector("list", n_reps)
mc_eff <- vector("list", n_reps)

# Efficiency-recovery statistics for one fitted metafrontier object
eff_stats <- function(fit, dat, method_label) {
  te  <- efficiencies(fit, type = "group")
  tes <- efficiencies(fit, type = "meta")
  tgr <- efficiencies(fit, type = "tgr")
  data.frame(
    method = method_label,
    te_true = mean(dat$true_te),   te_est = mean(te),
    rho_te = cor(te, dat$true_te, method = "spearman"),
    tes_true = mean(dat$true_te_star), tes_est = mean(tes),
    rho_tes = cor(tes, dat$true_te_star, method = "spearman"),
    tgr_true = mean(dat$true_tgr), tgr_est = mean(tgr),
    rho_tgr = suppressWarnings(
      cor(tgr, dat$true_tgr, method = "spearman"))
  )
}

for (r in seq_len(n_reps)) {
  sim_mc <- simulate_metafrontier(
    n_groups = 2, n_per_group = 100,
    beta_meta = beta_true,
    tech_gap = c(0, 0.4),
    sigma_u = c(0.2, 0.3),
    sigma_v = 0.15,
    seed = r * 1000
  )

  fit_d <- tryCatch(
    metafrontier(log_y ~ log_x1 + log_x2, data = sim_mc$data,
                 group = "group", method = "sfa",
                 meta_type = "deterministic"),
    error = function(e) NULL
  )
  fit_s <- tryCatch(
    metafrontier(log_y ~ log_x1 + log_x2, data = sim_mc$data,
                 group = "group", method = "sfa",
                 meta_type = "stochastic"),
    error = function(e) NULL
  )
  fit_dea <- tryCatch(
    metafrontier(log_y ~ log_x1 + log_x2, data = sim_mc$data,
                 group = "group", method = "dea",
                 orientation = "output", rts = "vrs"),
    error = function(e) NULL
  )

  if (!is.null(fit_d) && !is.null(fit_s)) {
    beta_d <- coef(fit_d)
    beta_s <- coef(fit_s)
    tgr_d <- efficiencies(fit_d, type = "tgr")
    tgr_s <- efficiencies(fit_s, type = "tgr")
    true_tgr <- sim_mc$data$true_tgr

    mc_results[[r]] <- data.frame(
      rep = r,
      method = rep(c("Deterministic", "Stochastic"), each = 3),
      parameter = rep(c("Intercept", "beta_1", "beta_2"), 2),
      true = rep(beta_true, 2),
      estimate = c(beta_d[1:3], beta_s[1:3]),
      mean_tgr_est = rep(c(mean(tgr_d), mean(tgr_s)), each = 3),
      mean_tgr_true = rep(mean(true_tgr), 6),
      tgr_corr = rep(c(cor(tgr_d, true_tgr, method = "spearman"),
                        cor(tgr_s, true_tgr, method = "spearman")), each = 3)
    )
  }
  if (!is.null(fit_d) && !is.null(fit_s) && !is.null(fit_dea)) {
    mc_eff[[r]] <- rbind(
      eff_stats(fit_d,   sim_mc$data, "Deterministic SFA"),
      eff_stats(fit_s,   sim_mc$data, "Stochastic SFA"),
      eff_stats(fit_dea, sim_mc$data, "DEA (VRS)")
    )
  }
}

mc_df <- do.call(rbind, mc_results)
mc_df$bias <- mc_df$estimate - mc_df$true
mc_eff_df <- do.call(rbind, mc_eff)


## ----mc-results, echo=FALSE-------------------------------------------
n_successful <- length(unique(mc_df$rep))
mc_summary <- aggregate(
  cbind(bias, estimate) ~ method + parameter,
  data = mc_df,
  FUN = function(x) c(mean = mean(x), sd = sd(x))
)
mc_tab <- data.frame(
  Parameter = mc_summary$parameter,
  Method = mc_summary$method,
  True = beta_true[match(mc_summary$parameter,
                         c("Intercept", "beta_1", "beta_2"))],
  Bias = mc_summary$bias[, "mean"],
  `MC SE` = mc_summary$estimate[, "sd"] / sqrt(n_successful),
  SD = mc_summary$estimate[, "sd"],
  RMSE = sqrt(mc_summary$bias[, "mean"]^2 + mc_summary$estimate[, "sd"]^2),
  check.names = FALSE
)
mc_tab <- mc_tab[order(mc_tab$Parameter, mc_tab$Method), ]
knitr::kable(mc_tab, digits = 4, row.names = FALSE,
             caption = paste0("Monte Carlo results for metafrontier coefficient estimation (", n_successful, " successful replications out of 500). MC SE is the Monte Carlo standard error of the mean estimate; RMSE is the root mean squared error."),
             align = "llccccc",
             booktabs = TRUE, linesep = "") |>
  ktbl()


## ----mc-lpqp, cache=TRUE, echo=FALSE----------------------------------
# LP vs QP objective: max abs TGR difference across Scenario A designs
lpqp_reps <- 50
lpqp_diff <- numeric(lpqp_reps)
for (r in seq_len(lpqp_reps)) {
  sim_lq <- simulate_metafrontier(
    n_groups = 2, n_per_group = 100, beta_meta = c(1.0, 0.5, 0.3),
    tech_gap = c(0, 0.4), sigma_u = c(0.2, 0.3), sigma_v = 0.15,
    seed = r * 1000
  )
  f_lp <- metafrontier(log_y ~ log_x1 + log_x2, data = sim_lq$data,
                       group = "group", objective = "lp")
  f_qp <- metafrontier(log_y ~ log_x1 + log_x2, data = sim_lq$data,
                       group = "group", objective = "qp")
  lpqp_diff[r] <- max(abs(f_lp$tgr - f_qp$tgr))
}
max_lpqp_diff <- max(lpqp_diff)


