## ----mc-small-n, cache=TRUE, echo=FALSE-------------------------------
set.seed(456)
n_reps_small <- 500
mc_small <- vector("list", n_reps_small)

for (r in seq_len(n_reps_small)) {
  sim_s <- simulate_metafrontier(
    n_groups = 2, n_per_group = 30,
    beta_meta = c(1.0, 0.5, 0.3),
    tech_gap = c(0, 0.4),
    sigma_u = c(0.2, 0.3),
    sigma_v = 0.15,
    seed = r * 2000
  )
  fit_ds <- tryCatch(
    metafrontier(log_y ~ log_x1 + log_x2, data = sim_s$data,
                 group = "group", method = "sfa",
                 meta_type = "deterministic"),
    error = function(e) NULL
  )
  if (!is.null(fit_ds)) {
    mc_small[[r]] <- list(
      det_coef = coef(fit_ds),
      det_tgr_cor = cor(efficiencies(fit_ds, type = "tgr"),
                        sim_s$data$true_tgr, method = "spearman")
    )
  }
}
mc_small <- mc_small[!sapply(mc_small, is.null)]
n_small_ok <- length(mc_small)
det_bias_small <- rowMeans(sapply(mc_small, function(x) x$det_coef)) - beta_true
det_tgr_small <- mean(sapply(mc_small, function(x) x$det_tgr_cor))


## ----mc-unbalanced, cache=TRUE, echo=FALSE----------------------------
set.seed(789)
n_reps_unb <- 500
mc_unb <- vector("list", n_reps_unb)

for (r in seq_len(n_reps_unb)) {
  sim_u <- simulate_metafrontier(
    n_groups = 2, n_per_group = c(200, 20),
    beta_meta = c(1.0, 0.5, 0.3),
    tech_gap = c(0, 0.4),
    sigma_u = c(0.2, 0.3),
    sigma_v = 0.15,
    seed = r * 4000
  )
  fit_u <- tryCatch(
    metafrontier(log_y ~ log_x1 + log_x2, data = sim_u$data,
                 group = "group", method = "sfa",
                 meta_type = "deterministic"),
    error = function(e) NULL
  )
  if (!is.null(fit_u)) {
    small_idx <- sim_u$data$group == "G2"
    tgr_u <- efficiencies(fit_u, type = "tgr")
    codes <- c(vapply(fit_u$group_models,
                      function(m) m$convergence, integer(1)),
               fit_u$meta_convergence)
    mc_unb[[r]] <- list(
      coef = coef(fit_u),
      all_zero = all(codes == 0L),
      tgr_cor = cor(tgr_u, sim_u$data$true_tgr, method = "spearman"),
      tgr_bias_small = mean(tgr_u[small_idx]) -
        mean(sim_u$data$true_tgr[small_idx])
    )
  }
}
mc_unb <- mc_unb[!sapply(mc_unb, is.null)]
n_unb_ok <- length(mc_unb)
n_unb_zero <- sum(sapply(mc_unb, function(x) x$all_zero))
unb_bias <- rowMeans(sapply(mc_unb, function(x) x$coef)) - c(1.0, 0.5, 0.3)
unb_tgr_cor <- mean(sapply(mc_unb, function(x) x$tgr_cor))
unb_tgr_bias_small <- mean(sapply(mc_unb, function(x) x$tgr_bias_small))


